// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title FXHedgingVault
 * @author Aethelred Team
 * @notice Currency risk management contract for the NoblePay cross-border
 *         payment platform. Provides forward contracts, options-style hedging,
 *         multi-currency vault positions, oracle-driven FX rate feeds,
 *         mark-to-market valuation, and IFRS 9 compliance tracking.
 *
 * @dev Architecture overview:
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │                      FX HEDGING VAULT                             │
 * ├───────────────────────────────────────────────────────────────────┤
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Forwards        │  │  Options          │  │  Oracle        │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • lock rate     │  │  • pay premium    │  │  • rate feeds  │  │
 * │  │  • settle at     │  │  • upside cap     │  │  • multi-src   │  │
 * │  │    maturity       │  │  • exercise       │  │  • staleness   │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Portfolio        │  │  Margin           │  │  Compliance    │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • multi-ccy     │  │  • requirements   │  │  • IFRS 9      │  │
 * │  │  • netting       │  │  • liquidation    │  │  • hedge eff.  │  │
 * │  │  • rebalance     │  │  • margin calls   │  │  • audit trail │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * Supported currency pairs:
 *   AED/USD, GBP/USD, EUR/USD, JPY/USD, CHF/USD, SGD/USD, HKD/USD,
 *   SAR/USD, CNY/USD, INR/USD
 *
 * Rate representation:
 *   All FX rates are stored with 8 decimal precision (1 USD = 1_00000000).
 *   Example: AED/USD at 3.6725 is stored as 3_67250000.
 */
contract FXHedgingVault is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ──────────────────────────────────────────────────────────────
    // Roles
    // ──────────────────────────────────────────────────────────────

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant ORACLE_ROLE = keccak256("ORACLE_ROLE");
    bytes32 public constant RISK_MANAGER_ROLE = keccak256("RISK_MANAGER_ROLE");
    bytes32 public constant LIQUIDATOR_ROLE = keccak256("LIQUIDATOR_ROLE");

    // ──────────────────────────────────────────────────────────────
    // Enums
    // ──────────────────────────────────────────────────────────────

    /// @notice Type of hedging instrument.
    enum HedgeType {
        FORWARD,        // Obligatory — must settle at locked rate
        OPTION_CALL,    // Right to buy base currency at strike
        OPTION_PUT      // Right to sell base currency at strike
    }

    /// @notice Lifecycle status of a hedging position.
    enum PositionStatus {
        ACTIVE,
        MATURED,
        SETTLED,
        EXERCISED,
        EXPIRED,
        LIQUIDATED,
        EMERGENCY_UNWOUND
    }

    // ──────────────────────────────────────────────────────────────
    // Structs
    // ──────────────────────────────────────────────────────────────

    /// @notice FX rate data from oracle.
    struct FXRate {
        bytes32 pairId;              // e.g., keccak256("AED/USD")
        uint256 rate;                // 8-decimal precision
        uint256 updatedAt;
        address submittedBy;
    }

    /// @notice Currency pair configuration.
    struct CurrencyPair {
        bytes3 baseCurrency;         // e.g., "AED"
        bytes3 quoteCurrency;        // e.g., "USD"
        bytes32 pairId;              // keccak256(baseCurrency, quoteCurrency)
        bool active;
        uint256 maxHedgeRatio;       // Maximum hedge ratio in basis points (10000 = 100%)
        uint256 marginRequirementBps; // Initial margin in basis points
        uint256 maintenanceMarginBps; // Maintenance margin in basis points
    }

    /// @notice Hedging position record.
    struct HedgePosition {
        bytes32 positionId;
        address hedger;              // Business hedging their exposure
        bytes32 pairId;              // Currency pair being hedged
        HedgeType hedgeType;
        PositionStatus status;
        uint256 notionalAmount;      // Notional amount in base currency (8 dec)
        uint256 lockedRate;          // Locked/strike FX rate (8 dec)
        uint256 premium;             // Premium paid for options (0 for forwards)
        address collateralToken;     // Stablecoin used as collateral
        uint256 collateralAmount;    // Margin deposited
        uint256 createdAt;
        uint256 maturityDate;
        uint256 settledAt;
        uint256 settlementAmount;    // Final settlement amount
        uint256 markToMarketValue;   // Latest MtM valuation
        uint256 lastMtMUpdate;
    }

    /// @notice Portfolio-level hedge summary for a business.
    struct HedgePortfolio {
        uint256 totalNotional;       // Total notional across all positions
        uint256 totalCollateral;     // Total collateral deposited
        uint256 totalPremiumPaid;    // Total premiums paid for options
        uint256 totalPnL;            // Cumulative realized P&L
        uint256 unrealizedPnL;       // Current unrealized P&L
        uint256 positionCount;       // Number of active positions
        uint256 lastRebalanced;
    }

    /// @notice Hedge effectiveness measurement for IFRS 9 compliance.
    struct HedgeEffectiveness {
        bytes32 positionId;
        uint256 hedgedItemChange;    // Change in value of hedged item
        uint256 hedgingInstrChange;  // Change in value of hedging instrument
        uint256 effectivenessRatio;  // Ratio in basis points (8000-12500 for valid hedge)
        uint256 measuredAt;
        bool isEffective;            // True if ratio is within 80%-125%
    }

    // ──────────────────────────────────────────────────────────────
    // Constants
    // ──────────────────────────────────────────────────────────────

    /// @notice FX rate precision (8 decimals).
    uint256 public constant RATE_PRECISION = 1e8;

    /// @notice Maximum staleness for FX rates (5 minutes).
    uint256 public constant MAX_RATE_STALENESS = 5 minutes;

    /// @notice Minimum hedge effectiveness ratio (80% = 8000 bps).
    uint256 public constant MIN_HEDGE_EFFECTIVENESS = 8000;

    /// @notice Maximum hedge effectiveness ratio (125% = 12500 bps).
    uint256 public constant MAX_HEDGE_EFFECTIVENESS = 12500;

    /// @notice Maximum position maturity (2 years).
    uint256 public constant MAX_MATURITY = 730 days;

    /// @notice Liquidation bonus in basis points (5%).
    uint256 public constant LIQUIDATION_BONUS_BPS = 500;

    /// @notice Maximum number of active positions per business.
    uint256 public constant MAX_POSITIONS_PER_BUSINESS = 100;

    // ──────────────────────────────────────────────────────────────
    // State
    // ──────────────────────────────────────────────────────────────

    /// @notice Currency pair configurations keyed by pair ID.
    mapping(bytes32 => CurrencyPair) public currencyPairs;

    /// @notice Active currency pair IDs.
    bytes32[] public activePairIds;

    /// @notice Latest FX rates keyed by pair ID.
    mapping(bytes32 => FXRate) public latestRates;

    /// @notice Hedge positions keyed by position ID.
    mapping(bytes32 => HedgePosition) public positions;

    /// @notice Portfolio summaries keyed by business address.
    mapping(address => HedgePortfolio) public portfolios;

    /// @notice Position IDs per business.
    mapping(address => bytes32[]) public businessPositions;

    /// @notice Hedge effectiveness records keyed by position ID.
    mapping(bytes32 => HedgeEffectiveness) public hedgeEffectiveness;

    /// @notice Supported collateral tokens (stablecoins).
    mapping(address => bool) public supportedCollateral;

    /// @notice Protocol treasury for premium and fee collection.
    address public treasury;

    /// @notice Position nonce for unique ID generation.
    uint256 public positionNonce;

    /// @notice Protocol fee on forward settlements in basis points.
    uint256 public settlementFeeBps;

    // ──────────────────────────────────────────────────────────────
    // Events
    // ──────────────────────────────────────────────────────────────

    event CurrencyPairAdded(
        bytes32 indexed pairId,
        bytes3 baseCurrency,
        bytes3 quoteCurrency,
        uint256 marginRequirementBps
    );

    event CurrencyPairUpdated(bytes32 indexed pairId, bool active);

    event FXRateUpdated(
        bytes32 indexed pairId,
        uint256 rate,
        uint256 timestamp,
        address indexed oracle
    );

    event ForwardCreated(
        bytes32 indexed positionId,
        address indexed hedger,
        bytes32 indexed pairId,
        uint256 notionalAmount,
        uint256 lockedRate,
        uint256 maturityDate
    );

    event OptionCreated(
        bytes32 indexed positionId,
        address indexed hedger,
        bytes32 indexed pairId,
        HedgeType hedgeType,
        uint256 notionalAmount,
        uint256 strikeRate,
        uint256 premium
    );

    event PositionSettled(
        bytes32 indexed positionId,
        address indexed hedger,
        uint256 settlementAmount,
        int256 pnl
    );

    event OptionExercised(
        bytes32 indexed positionId,
        address indexed hedger,
        uint256 exerciseRate,
        uint256 settlementAmount
    );

    event OptionExpired(bytes32 indexed positionId);

    event PositionLiquidated(
        bytes32 indexed positionId,
        address indexed liquidator,
        uint256 collateralSeized,
        uint256 liquidationBonus
    );

    event MarginAdded(
        bytes32 indexed positionId,
        address indexed hedger,
        uint256 amount
    );

    event MarkToMarketUpdated(
        bytes32 indexed positionId,
        uint256 mtmValue,
        uint256 timestamp
    );

    event HedgeEffectivenessAssessed(
        bytes32 indexed positionId,
        uint256 effectivenessRatio,
        bool isEffective
    );

    event PortfolioRebalanced(
        address indexed hedger,
        uint256 positionsAdjusted,
        uint256 timestamp
    );

    event EmergencyUnwind(
        bytes32 indexed positionId,
        uint256 unwindAmount,
        uint256 timestamp
    );

    event CollateralTokenUpdated(address indexed token, bool supported);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event SettlementFeeUpdated(uint256 oldFee, uint256 newFee);

    // ──────────────────────────────────────────────────────────────
    // Errors
    // ──────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroAmount();
    error UnsupportedCollateral();
    error PairNotFound();
    error PairNotActive();
    error PositionNotFound();
    error InvalidPositionStatus(PositionStatus current);
    error RateStale(uint256 updatedAt, uint256 maxAge);
    error MaturityInPast();
    error MaturityTooFar();
    error InsufficientMargin(uint256 provided, uint256 required);
    error NotPositionOwner();
    error PositionNotMatured();
    error OptionNotInTheMoney();
    error MarginSufficient();
    error MaxPositionsReached();
    error PairAlreadyExists();
    error InvalidFee();
    error InvalidRate();

    // ──────────────────────────────────────────────────────────────
    // Constructor
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Deploys FXHedgingVault.
     * @param _admin           Admin address.
     * @param _treasury        Treasury address for fee collection.
     * @param _settlementFeeBps Settlement fee in basis points.
     */
    constructor(
        address _admin,
        address _treasury,
        uint256 _settlementFeeBps
    ) {
        if (_admin == address(0)) revert ZeroAddress();
        if (_treasury == address(0)) revert ZeroAddress();
        if (_settlementFeeBps > 500) revert InvalidFee(); // Max 5%

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);

        treasury = _treasury;
        settlementFeeBps = _settlementFeeBps;
    }

    // ──────────────────────────────────────────────────────────────
    // External — Oracle Rate Submission
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Submits a new FX rate from an authorized oracle.
     * @param _pairId  Currency pair identifier.
     * @param _rate    FX rate with 8-decimal precision.
     */
    function submitFXRate(
        bytes32 _pairId,
        uint256 _rate
    ) external onlyRole(ORACLE_ROLE) whenNotPaused {
        if (currencyPairs[_pairId].pairId == bytes32(0)) revert PairNotFound();
        if (_rate == 0) revert InvalidRate();

        latestRates[_pairId] = FXRate({
            pairId: _pairId,
            rate: _rate,
            updatedAt: block.timestamp,
            submittedBy: msg.sender
        });

        emit FXRateUpdated(_pairId, _rate, block.timestamp, msg.sender);
    }

    /**
     * @notice Batch submits FX rates for multiple currency pairs.
     * @param _pairIds Array of pair IDs.
     * @param _rates   Array of corresponding rates.
     */
    function batchSubmitFXRates(
        bytes32[] calldata _pairIds,
        uint256[] calldata _rates
    ) external onlyRole(ORACLE_ROLE) whenNotPaused {
        require(_pairIds.length == _rates.length, "FXHedgingVault: array mismatch");

        for (uint256 i; i < _pairIds.length;) {
            if (currencyPairs[_pairIds[i]].pairId == bytes32(0)) revert PairNotFound();
            if (_rates[i] == 0) revert InvalidRate();

            latestRates[_pairIds[i]] = FXRate({
                pairId: _pairIds[i],
                rate: _rates[i],
                updatedAt: block.timestamp,
                submittedBy: msg.sender
            });

            emit FXRateUpdated(_pairIds[i], _rates[i], block.timestamp, msg.sender);

            unchecked { ++i; }
        }
    }

    // ──────────────────────────────────────────────────────────────
    // External — Forward Contracts
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates a forward contract to lock in an FX rate for future settlement.
     * @param _pairId          Currency pair to hedge.
     * @param _notionalAmount  Notional amount in base currency (8 dec).
     * @param _maturityDate    Settlement date for the forward.
     * @param _collateralToken Stablecoin used as margin collateral.
     * @param _collateralAmount Initial margin deposit.
     * @return positionId      Unique position identifier.
     */
    function createForward(
        bytes32 _pairId,
        uint256 _notionalAmount,
        uint256 _maturityDate,
        address _collateralToken,
        uint256 _collateralAmount
    ) external whenNotPaused nonReentrant returns (bytes32 positionId) {
        _validateNewPosition(_pairId, _notionalAmount, _maturityDate, _collateralToken);

        // Get current rate as the locked rate
        FXRate storage currentRate = latestRates[_pairId];
        _requireFreshRate(currentRate);

        // Validate margin requirement
        CurrencyPair storage pair = currencyPairs[_pairId];
        uint256 requiredMargin = (_notionalAmount * pair.marginRequirementBps) / 10_000;
        if (_collateralAmount < requiredMargin) {
            revert InsufficientMargin(_collateralAmount, requiredMargin);
        }

        positionId = keccak256(
            abi.encodePacked(msg.sender, _pairId, _notionalAmount, block.timestamp, positionNonce++)
        );

        positions[positionId] = HedgePosition({
            positionId: positionId,
            hedger: msg.sender,
            pairId: _pairId,
            hedgeType: HedgeType.FORWARD,
            status: PositionStatus.ACTIVE,
            notionalAmount: _notionalAmount,
            lockedRate: currentRate.rate,
            premium: 0,
            collateralToken: _collateralToken,
            collateralAmount: _collateralAmount,
            createdAt: block.timestamp,
            maturityDate: _maturityDate,
            settledAt: 0,
            settlementAmount: 0,
            markToMarketValue: _notionalAmount,
            lastMtMUpdate: block.timestamp
        });

        // Update portfolio
        HedgePortfolio storage portfolio = portfolios[msg.sender];
        portfolio.totalNotional += _notionalAmount;
        portfolio.totalCollateral += _collateralAmount;
        portfolio.positionCount++;
        businessPositions[msg.sender].push(positionId);

        // Transfer collateral
        IERC20(_collateralToken).safeTransferFrom(msg.sender, address(this), _collateralAmount);

        emit ForwardCreated(positionId, msg.sender, _pairId, _notionalAmount, currentRate.rate, _maturityDate);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Options
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates an options-style hedge with premium payment.
     * @dev The hedger pays a premium for the right (not obligation) to
     *      exchange at the strike rate. Allows upside participation.
     * @param _pairId          Currency pair to hedge.
     * @param _hedgeType       OPTION_CALL or OPTION_PUT.
     * @param _notionalAmount  Notional amount in base currency (8 dec).
     * @param _strikeRate      Strike FX rate (8 dec).
     * @param _premium         Premium to pay for the option.
     * @param _maturityDate    Expiry date of the option.
     * @param _collateralToken Stablecoin for premium payment.
     * @param _collateralAmount Margin collateral for the position.
     * @return positionId      Unique position identifier.
     */
    function createOption(
        bytes32 _pairId,
        HedgeType _hedgeType,
        uint256 _notionalAmount,
        uint256 _strikeRate,
        uint256 _premium,
        uint256 _maturityDate,
        address _collateralToken,
        uint256 _collateralAmount
    ) external whenNotPaused nonReentrant returns (bytes32 positionId) {
        require(
            _hedgeType == HedgeType.OPTION_CALL || _hedgeType == HedgeType.OPTION_PUT,
            "FXHedgingVault: invalid option type"
        );
        _validateNewPosition(_pairId, _notionalAmount, _maturityDate, _collateralToken);
        if (_strikeRate == 0) revert InvalidRate();

        positionId = keccak256(
            abi.encodePacked(msg.sender, _pairId, _notionalAmount, _strikeRate, block.timestamp, positionNonce++)
        );

        positions[positionId] = HedgePosition({
            positionId: positionId,
            hedger: msg.sender,
            pairId: _pairId,
            hedgeType: _hedgeType,
            status: PositionStatus.ACTIVE,
            notionalAmount: _notionalAmount,
            lockedRate: _strikeRate,
            premium: _premium,
            collateralToken: _collateralToken,
            collateralAmount: _collateralAmount,
            createdAt: block.timestamp,
            maturityDate: _maturityDate,
            settledAt: 0,
            settlementAmount: 0,
            markToMarketValue: _notionalAmount,
            lastMtMUpdate: block.timestamp
        });

        // Update portfolio
        HedgePortfolio storage portfolio = portfolios[msg.sender];
        portfolio.totalNotional += _notionalAmount;
        portfolio.totalCollateral += _collateralAmount;
        portfolio.totalPremiumPaid += _premium;
        portfolio.positionCount++;
        businessPositions[msg.sender].push(positionId);

        // Transfer collateral + premium
        uint256 totalDeposit = _collateralAmount + _premium;
        IERC20(_collateralToken).safeTransferFrom(msg.sender, address(this), totalDeposit);

        // Send premium to treasury
        if (_premium > 0) {
            IERC20(_collateralToken).safeTransfer(treasury, _premium);
        }

        emit OptionCreated(positionId, msg.sender, _pairId, _hedgeType, _notionalAmount, _strikeRate, _premium);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Settlement & Exercise
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Settles a matured forward contract.
     * @dev Calculates P&L based on locked rate vs. spot rate at maturity.
     * @param _positionId Position to settle.
     */
    function settleForward(bytes32 _positionId) external whenNotPaused nonReentrant {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.hedger != msg.sender && !hasRole(ADMIN_ROLE, msg.sender)) revert NotPositionOwner();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);
        if (pos.hedgeType != HedgeType.FORWARD) revert InvalidPositionStatus(pos.status);
        if (block.timestamp < pos.maturityDate) revert PositionNotMatured();

        FXRate storage currentRate = latestRates[pos.pairId];
        _requireFreshRate(currentRate);

        // Calculate settlement: difference between locked and spot rate applied to notional
        int256 pnl;
        uint256 settlementAmount;

        if (currentRate.rate >= pos.lockedRate) {
            // Rate moved favorably (base currency appreciated)
            uint256 gain = ((currentRate.rate - pos.lockedRate) * pos.notionalAmount) / RATE_PRECISION;
            settlementAmount = pos.collateralAmount + gain;
            pnl = int256(gain);
        } else {
            // Rate moved unfavorably (base currency depreciated)
            uint256 loss = ((pos.lockedRate - currentRate.rate) * pos.notionalAmount) / RATE_PRECISION;
            settlementAmount = loss >= pos.collateralAmount ? 0 : pos.collateralAmount - loss;
            pnl = -int256(loss);
        }

        // Apply settlement fee
        uint256 fee = (pos.collateralAmount * settlementFeeBps) / 10_000;
        if (settlementAmount > fee) {
            settlementAmount -= fee;
        } else {
            fee = settlementAmount;
            settlementAmount = 0;
        }

        pos.status = PositionStatus.SETTLED;
        pos.settledAt = block.timestamp;
        pos.settlementAmount = settlementAmount;

        // Update portfolio
        HedgePortfolio storage portfolio = portfolios[pos.hedger];
        portfolio.totalNotional -= pos.notionalAmount;
        portfolio.totalCollateral -= pos.collateralAmount;
        portfolio.positionCount--;
        if (pnl > 0) {
            portfolio.totalPnL += uint256(pnl);
        }

        // Transfer settlement
        if (settlementAmount > 0) {
            IERC20(pos.collateralToken).safeTransfer(pos.hedger, settlementAmount);
        }
        if (fee > 0) {
            IERC20(pos.collateralToken).safeTransfer(treasury, fee);
        }

        emit PositionSettled(_positionId, pos.hedger, settlementAmount, pnl);
    }

    /**
     * @notice Exercises an in-the-money option before or at expiry.
     * @param _positionId Option position to exercise.
     */
    function exerciseOption(bytes32 _positionId) external whenNotPaused nonReentrant {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.hedger != msg.sender) revert NotPositionOwner();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);
        require(
            pos.hedgeType == HedgeType.OPTION_CALL || pos.hedgeType == HedgeType.OPTION_PUT,
            "FXHedgingVault: not an option"
        );
        if (block.timestamp > pos.maturityDate) revert PositionNotMatured();

        FXRate storage currentRate = latestRates[pos.pairId];
        _requireFreshRate(currentRate);

        // Check if option is in-the-money
        bool inTheMoney;
        uint256 intrinsicValue;

        if (pos.hedgeType == HedgeType.OPTION_CALL) {
            // Call is ITM when spot > strike
            inTheMoney = currentRate.rate > pos.lockedRate;
            if (inTheMoney) {
                intrinsicValue = ((currentRate.rate - pos.lockedRate) * pos.notionalAmount) / RATE_PRECISION;
            }
        } else {
            // Put is ITM when spot < strike
            inTheMoney = currentRate.rate < pos.lockedRate;
            if (inTheMoney) {
                intrinsicValue = ((pos.lockedRate - currentRate.rate) * pos.notionalAmount) / RATE_PRECISION;
            }
        }

        if (!inTheMoney) revert OptionNotInTheMoney();

        uint256 settlementAmount = pos.collateralAmount + intrinsicValue;
        uint256 fee = (intrinsicValue * settlementFeeBps) / 10_000;
        settlementAmount -= fee;

        pos.status = PositionStatus.EXERCISED;
        pos.settledAt = block.timestamp;
        pos.settlementAmount = settlementAmount;

        // Update portfolio
        HedgePortfolio storage portfolio = portfolios[pos.hedger];
        portfolio.totalNotional -= pos.notionalAmount;
        portfolio.totalCollateral -= pos.collateralAmount;
        portfolio.positionCount--;
        portfolio.totalPnL += intrinsicValue;

        IERC20(pos.collateralToken).safeTransfer(pos.hedger, settlementAmount);
        if (fee > 0) {
            IERC20(pos.collateralToken).safeTransfer(treasury, fee);
        }

        emit OptionExercised(_positionId, pos.hedger, currentRate.rate, settlementAmount);
    }

    /**
     * @notice Marks an expired option as expired and returns collateral.
     * @param _positionId Option that has expired without exercise.
     */
    function expireOption(bytes32 _positionId) external whenNotPaused nonReentrant {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);
        require(
            pos.hedgeType == HedgeType.OPTION_CALL || pos.hedgeType == HedgeType.OPTION_PUT,
            "FXHedgingVault: not an option"
        );
        if (block.timestamp <= pos.maturityDate) revert PositionNotMatured();

        pos.status = PositionStatus.EXPIRED;
        pos.settledAt = block.timestamp;

        // Return collateral (premium already taken)
        HedgePortfolio storage portfolio = portfolios[pos.hedger];
        portfolio.totalNotional -= pos.notionalAmount;
        portfolio.totalCollateral -= pos.collateralAmount;
        portfolio.positionCount--;

        if (pos.collateralAmount > 0) {
            IERC20(pos.collateralToken).safeTransfer(pos.hedger, pos.collateralAmount);
        }

        emit OptionExpired(_positionId);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Margin & Liquidation
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Adds additional margin to an existing position.
     * @param _positionId Position to add margin to.
     * @param _amount     Amount of additional collateral.
     */
    function addMargin(
        bytes32 _positionId,
        uint256 _amount
    ) external whenNotPaused nonReentrant {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.hedger != msg.sender) revert NotPositionOwner();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);
        if (_amount == 0) revert ZeroAmount();

        pos.collateralAmount += _amount;
        portfolios[msg.sender].totalCollateral += _amount;

        IERC20(pos.collateralToken).safeTransferFrom(msg.sender, address(this), _amount);

        emit MarginAdded(_positionId, msg.sender, _amount);
    }

    /**
     * @notice Liquidates an under-margined position.
     * @dev Callable by liquidators when collateral drops below maintenance margin.
     * @param _positionId Position to liquidate.
     */
    function liquidatePosition(
        bytes32 _positionId
    ) external whenNotPaused nonReentrant onlyRole(LIQUIDATOR_ROLE) {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);

        FXRate storage currentRate = latestRates[pos.pairId];
        _requireFreshRate(currentRate);

        // Calculate current margin ratio
        CurrencyPair storage pair = currencyPairs[pos.pairId];
        uint256 maintenanceMargin = (pos.notionalAmount * pair.maintenanceMarginBps) / 10_000;

        // Calculate unrealized loss
        uint256 unrealizedLoss;
        if (pos.hedgeType == HedgeType.FORWARD) {
            if (currentRate.rate < pos.lockedRate) {
                unrealizedLoss = ((pos.lockedRate - currentRate.rate) * pos.notionalAmount) / RATE_PRECISION;
            }
        }

        uint256 effectiveCollateral = unrealizedLoss >= pos.collateralAmount
            ? 0
            : pos.collateralAmount - unrealizedLoss;

        if (effectiveCollateral >= maintenanceMargin) revert MarginSufficient();

        // Liquidate
        uint256 liquidationBonus = (pos.collateralAmount * LIQUIDATION_BONUS_BPS) / 10_000;
        uint256 liquidatorReward = liquidationBonus > pos.collateralAmount
            ? pos.collateralAmount
            : liquidationBonus;
        uint256 remainder = pos.collateralAmount - liquidatorReward;

        pos.status = PositionStatus.LIQUIDATED;
        pos.settledAt = block.timestamp;

        // Update portfolio
        HedgePortfolio storage portfolio = portfolios[pos.hedger];
        portfolio.totalNotional -= pos.notionalAmount;
        portfolio.totalCollateral -= pos.collateralAmount;
        portfolio.positionCount--;

        // Transfer rewards
        if (liquidatorReward > 0) {
            IERC20(pos.collateralToken).safeTransfer(msg.sender, liquidatorReward);
        }
        if (remainder > 0) {
            IERC20(pos.collateralToken).safeTransfer(pos.hedger, remainder);
        }

        emit PositionLiquidated(_positionId, msg.sender, pos.collateralAmount, liquidatorReward);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Mark-to-Market & Hedge Effectiveness
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Updates mark-to-market valuation for a position.
     * @param _positionId Position to revalue.
     */
    function updateMarkToMarket(bytes32 _positionId) external whenNotPaused {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);

        FXRate storage currentRate = latestRates[pos.pairId];
        _requireFreshRate(currentRate);

        // MtM = notional valued at current rate
        uint256 mtmValue = (pos.notionalAmount * currentRate.rate) / RATE_PRECISION;
        pos.markToMarketValue = mtmValue;
        pos.lastMtMUpdate = block.timestamp;

        // Update portfolio unrealized P&L
        uint256 originalValue = (pos.notionalAmount * pos.lockedRate) / RATE_PRECISION;
        if (mtmValue >= originalValue) {
            portfolios[pos.hedger].unrealizedPnL += (mtmValue - originalValue);
        }

        emit MarkToMarketUpdated(_positionId, mtmValue, block.timestamp);
    }

    /**
     * @notice Assesses hedge effectiveness for IFRS 9 compliance.
     * @dev Measures the ratio of hedged item value change to hedging
     *      instrument value change. Valid hedge: 80%-125%.
     * @param _positionId        Position to assess.
     * @param _hedgedItemChange  Change in value of the hedged item.
     */
    function assessHedgeEffectiveness(
        bytes32 _positionId,
        uint256 _hedgedItemChange
    ) external onlyRole(RISK_MANAGER_ROLE) whenNotPaused {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();

        FXRate storage currentRate = latestRates[pos.pairId];
        _requireFreshRate(currentRate);

        // Calculate hedging instrument change
        uint256 originalValue = (pos.notionalAmount * pos.lockedRate) / RATE_PRECISION;
        uint256 currentValue = (pos.notionalAmount * currentRate.rate) / RATE_PRECISION;
        uint256 hedgingInstrChange = currentValue > originalValue
            ? currentValue - originalValue
            : originalValue - currentValue;

        // Calculate effectiveness ratio (in bps, 10000 = 100%)
        uint256 effectivenessRatio;
        if (_hedgedItemChange > 0) {
            effectivenessRatio = (hedgingInstrChange * 10_000) / _hedgedItemChange;
        }

        bool isEffective = effectivenessRatio >= MIN_HEDGE_EFFECTIVENESS &&
                           effectivenessRatio <= MAX_HEDGE_EFFECTIVENESS;

        hedgeEffectiveness[_positionId] = HedgeEffectiveness({
            positionId: _positionId,
            hedgedItemChange: _hedgedItemChange,
            hedgingInstrChange: hedgingInstrChange,
            effectivenessRatio: effectivenessRatio,
            measuredAt: block.timestamp,
            isEffective: isEffective
        });

        emit HedgeEffectivenessAssessed(_positionId, effectivenessRatio, isEffective);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Emergency
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Emergency unwind of a position by admin.
     * @dev Returns remaining collateral to the hedger.
     * @param _positionId Position to unwind.
     */
    function emergencyUnwind(
        bytes32 _positionId
    ) external onlyRole(ADMIN_ROLE) nonReentrant {
        HedgePosition storage pos = positions[_positionId];
        if (pos.createdAt == 0) revert PositionNotFound();
        if (pos.status != PositionStatus.ACTIVE) revert InvalidPositionStatus(pos.status);

        pos.status = PositionStatus.EMERGENCY_UNWOUND;
        pos.settledAt = block.timestamp;

        HedgePortfolio storage portfolio = portfolios[pos.hedger];
        portfolio.totalNotional -= pos.notionalAmount;
        portfolio.totalCollateral -= pos.collateralAmount;
        portfolio.positionCount--;

        if (pos.collateralAmount > 0) {
            IERC20(pos.collateralToken).safeTransfer(pos.hedger, pos.collateralAmount);
        }

        emit EmergencyUnwind(_positionId, pos.collateralAmount, block.timestamp);
    }

    // ──────────────────────────────────────────────────────────────
    // View Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Returns the latest FX rate for a currency pair.
    function getLatestRate(bytes32 _pairId) external view returns (uint256 rate, uint256 updatedAt) {
        FXRate storage r = latestRates[_pairId];
        return (r.rate, r.updatedAt);
    }

    /// @notice Returns a hedge position record.
    function getPosition(bytes32 _positionId) external view returns (HedgePosition memory) {
        return positions[_positionId];
    }

    /// @notice Returns a business's hedge portfolio summary.
    function getPortfolio(address _hedger) external view returns (HedgePortfolio memory) {
        return portfolios[_hedger];
    }

    /// @notice Returns all position IDs for a business.
    function getBusinessPositions(address _hedger) external view returns (bytes32[] memory) {
        return businessPositions[_hedger];
    }

    /// @notice Returns the hedge effectiveness for a position.
    function getHedgeEffectiveness(bytes32 _positionId) external view returns (HedgeEffectiveness memory) {
        return hedgeEffectiveness[_positionId];
    }

    /// @notice Returns all active currency pair IDs.
    function getActivePairs() external view returns (bytes32[] memory) {
        return activePairIds;
    }

    /// @notice Returns a currency pair configuration.
    function getCurrencyPair(bytes32 _pairId) external view returns (CurrencyPair memory) {
        return currencyPairs[_pairId];
    }

    /// @notice Checks whether a position is under-margined.
    function isUnderMargined(bytes32 _positionId) external view returns (bool) {
        HedgePosition storage pos = positions[_positionId];
        if (pos.status != PositionStatus.ACTIVE) return false;

        FXRate storage currentRate = latestRates[pos.pairId];
        if (block.timestamp > currentRate.updatedAt + MAX_RATE_STALENESS) return false;

        CurrencyPair storage pair = currencyPairs[pos.pairId];
        uint256 maintenanceMargin = (pos.notionalAmount * pair.maintenanceMarginBps) / 10_000;

        uint256 unrealizedLoss;
        if (pos.hedgeType == HedgeType.FORWARD && currentRate.rate < pos.lockedRate) {
            unrealizedLoss = ((pos.lockedRate - currentRate.rate) * pos.notionalAmount) / RATE_PRECISION;
        }

        uint256 effectiveCollateral = unrealizedLoss >= pos.collateralAmount
            ? 0
            : pos.collateralAmount - unrealizedLoss;

        return effectiveCollateral < maintenanceMargin;
    }

    // ──────────────────────────────────────────────────────────────
    // Admin Functions
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Adds a new currency pair.
     * @param _baseCurrency      3-byte ISO currency code.
     * @param _quoteCurrency     3-byte ISO currency code.
     * @param _maxHedgeRatio     Maximum hedge ratio in bps.
     * @param _marginReqBps      Initial margin requirement in bps.
     * @param _maintenanceMarginBps Maintenance margin in bps.
     */
    function addCurrencyPair(
        bytes3 _baseCurrency,
        bytes3 _quoteCurrency,
        uint256 _maxHedgeRatio,
        uint256 _marginReqBps,
        uint256 _maintenanceMarginBps
    ) external onlyRole(ADMIN_ROLE) {
        bytes32 pairId = keccak256(abi.encodePacked(_baseCurrency, _quoteCurrency));
        if (currencyPairs[pairId].pairId != bytes32(0)) revert PairAlreadyExists();

        currencyPairs[pairId] = CurrencyPair({
            baseCurrency: _baseCurrency,
            quoteCurrency: _quoteCurrency,
            pairId: pairId,
            active: true,
            maxHedgeRatio: _maxHedgeRatio,
            marginRequirementBps: _marginReqBps,
            maintenanceMarginBps: _maintenanceMarginBps
        });

        activePairIds.push(pairId);

        emit CurrencyPairAdded(pairId, _baseCurrency, _quoteCurrency, _marginReqBps);
    }

    /// @notice Activates or deactivates a currency pair.
    function setCurrencyPairActive(bytes32 _pairId, bool _active) external onlyRole(ADMIN_ROLE) {
        if (currencyPairs[_pairId].pairId == bytes32(0)) revert PairNotFound();
        currencyPairs[_pairId].active = _active;
        emit CurrencyPairUpdated(_pairId, _active);
    }

    /// @notice Adds or removes a supported collateral token.
    function setSupportedCollateral(address _token, bool _supported) external onlyRole(ADMIN_ROLE) {
        if (_token == address(0)) revert ZeroAddress();
        supportedCollateral[_token] = _supported;
        emit CollateralTokenUpdated(_token, _supported);
    }

    /// @notice Updates the treasury address.
    function setTreasury(address _newTreasury) external onlyRole(ADMIN_ROLE) {
        if (_newTreasury == address(0)) revert ZeroAddress();
        address old = treasury;
        treasury = _newTreasury;
        emit TreasuryUpdated(old, _newTreasury);
    }

    /// @notice Updates the settlement fee.
    function setSettlementFee(uint256 _newFeeBps) external onlyRole(ADMIN_ROLE) {
        if (_newFeeBps > 500) revert InvalidFee();
        uint256 oldFee = settlementFeeBps;
        settlementFeeBps = _newFeeBps;
        emit SettlementFeeUpdated(oldFee, _newFeeBps);
    }

    /// @notice Emergency pause.
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /// @notice Resume operations.
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // ──────────────────────────────────────────────────────────────
    // Internal Helpers
    // ──────────────────────────────────────────────────────────────

    /**
     * @dev Validates common parameters for new position creation.
     */
    function _validateNewPosition(
        bytes32 _pairId,
        uint256 _notionalAmount,
        uint256 _maturityDate,
        address _collateralToken
    ) internal view {
        CurrencyPair storage pair = currencyPairs[_pairId];
        if (pair.pairId == bytes32(0)) revert PairNotFound();
        if (!pair.active) revert PairNotActive();
        if (_notionalAmount == 0) revert ZeroAmount();
        if (_maturityDate <= block.timestamp) revert MaturityInPast();
        if (_maturityDate > block.timestamp + MAX_MATURITY) revert MaturityTooFar();
        if (!supportedCollateral[_collateralToken]) revert UnsupportedCollateral();
        if (businessPositions[msg.sender].length >= MAX_POSITIONS_PER_BUSINESS) {
            revert MaxPositionsReached();
        }
    }

    /**
     * @dev Requires that an FX rate is not stale.
     */
    function _requireFreshRate(FXRate storage _rate) internal view {
        if (_rate.updatedAt == 0 || block.timestamp > _rate.updatedAt + MAX_RATE_STALENESS) {
            revert RateStale(_rate.updatedAt, MAX_RATE_STALENESS);
        }
    }
}

src/InvoiceFinancing.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title InvoiceFinancing
 * @author Aethelred Team
 * @notice Trade finance and receivables factoring contract for the NoblePay
 *         cross-border payment platform. Enables tokenized invoice creation,
 *         factoring (selling receivables at discount for instant liquidity),
 *         multi-party invoice chains, on-chain credit scoring, and automated
 *         settlement with dispute resolution.
 *
 * @dev Architecture overview:
 *
 * ┌───────────────────────────────────────────────────────────────────┐
 * │                     INVOICE FINANCING                             │
 * ├───────────────────────────────────────────────────────────────────┤
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Invoice Mgmt    │  │  Factoring        │  │  Credit Score  │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • create        │  │  • full/partial   │  │  • on-chain    │  │
 * │  │  • batch upload  │  │  • dynamic rates  │  │  • history     │  │
 * │  │  • chain link    │  │  • collateral     │  │  • scoring     │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * │  ┌─────────────────┐  ┌──────────────────┐  ┌────────────────┐  │
 * │  │  Settlement      │  │  Disputes         │  │  Penalties     │  │
 * │  │  ──────────────  │  │  ──────────────── │  │  ──────────── │  │
 * │  │  • auto-settle   │  │  • escrow         │  │  • late fees   │  │
 * │  │  • partial pay   │  │  • arbitration    │  │  • grace period│  │
 * │  │  • fee split     │  │  • resolution     │  │  • credit hit  │  │
 * │  └─────────────────┘  └──────────────────┘  └────────────────┘  │
 * └───────────────────────────────────────────────────────────────────┘
 *
 * Invoice lifecycle:
 *   CREATED → FINANCED (partial/full) → SETTLED / OVERDUE → DISPUTED → RESOLVED
 *
 * Credit scoring:
 *   Each business accumulates an on-chain credit history based on payment
 *   behavior. Scores range 300-850 (similar to traditional credit) and
 *   influence discount rates offered by factors.
 */
contract InvoiceFinancing is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ──────────────────────────────────────────────────────────────
    // Roles
    // ──────────────────────────────────────────────────────────────

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant FACTOR_ROLE = keccak256("FACTOR_ROLE");
    bytes32 public constant CREDIT_ANALYST_ROLE = keccak256("CREDIT_ANALYST_ROLE");
    bytes32 public constant ARBITER_ROLE = keccak256("ARBITER_ROLE");

    // ──────────────────────────────────────────────────────────────
    // Enums
    // ──────────────────────────────────────────────────────────────

    /// @notice Lifecycle status of an invoice.
    enum InvoiceStatus {
        CREATED,
        PARTIALLY_FINANCED,
        FULLY_FINANCED,
        SETTLED,
        OVERDUE,
        DISPUTED,
        RESOLVED,
        CANCELLED
    }

    /// @notice Outcome of a dispute resolution.
    enum DisputeOutcome {
        PENDING,
        FAVOR_CREDITOR,
        FAVOR_DEBTOR,
        SPLIT
    }

    // ──────────────────────────────────────────────────────────────
    // Structs
    // ──────────────────────────────────────────────────────────────

    /// @notice Core invoice record representing a receivable.
    struct Invoice {
        bytes32 invoiceId;
        address creditor;             // Business that issued the invoice (seller)
        address debtor;               // Business that owes payment (buyer)
        uint256 faceValue;            // Original invoice amount
        uint256 amountFinanced;       // Total amount advanced by factors
        uint256 amountRepaid;         // Total amount repaid by debtor
        address settlementToken;      // ERC20 token for settlement
        uint256 issuedAt;
        uint256 maturityDate;         // When payment is due
        uint256 settledAt;
        InvoiceStatus status;
        bytes32 documentHash;         // Hash of off-chain invoice document
        bytes32 parentInvoiceId;      // For multi-party chains (0x0 if root)
        uint256 gracePeriod;          // Grace period in seconds after maturity
        uint256 latePenaltyBps;       // Late payment penalty in basis points
    }

    /// @notice Record of a factoring (financing) transaction.
    struct FactoringPosition {
        bytes32 positionId;
        bytes32 invoiceId;
        address factor;               // Entity providing financing
        uint256 advanceAmount;         // Amount advanced to creditor
        uint256 discountBps;           // Discount rate in basis points
        uint256 expectedReturn;        // Amount factor expects at maturity
        uint256 financedAt;
        bool settled;
        uint256 settledAmount;         // Actual amount received at settlement
    }

    /// @notice On-chain credit profile for a business.
    struct CreditProfile {
        uint16 creditScore;           // 300-850 scale
        uint256 totalInvoicesIssued;
        uint256 totalInvoicesPaid;
        uint256 totalInvoicesDefaulted;
        uint256 totalValueFinanced;
        uint256 totalValueRepaid;
        uint256 averageDaysLate;      // Weighted average days late
        uint256 lastUpdated;
    }

    /// @notice Dispute record for contested invoices.
    struct Dispute {
        bytes32 disputeId;
        bytes32 invoiceId;
        address initiator;
        address respondent;
        string reason;
        uint256 escrowAmount;         // Amount held in escrow during dispute
        DisputeOutcome outcome;
        uint256 initiatedAt;
        uint256 resolvedAt;
        address arbiter;
        uint256 creditorAward;        // Amount awarded to creditor
        uint256 debtorRefund;         // Amount refunded to debtor
    }

    /// @notice Collateral deposited against under-collateralized financing.
    struct Collateral {
        address depositor;
        address token;
        uint256 amount;
        bytes32 invoiceId;
        bool released;
    }

    // ──────────────────────────────────────────────────────────────
    // Constants
    // ──────────────────────────────────────────────────────────────

    /// @notice Minimum credit score.
    uint16 public constant MIN_CREDIT_SCORE = 300;

    /// @notice Maximum credit score.
    uint16 public constant MAX_CREDIT_SCORE = 850;

    /// @notice Default credit score for new businesses.
    uint16 public constant DEFAULT_CREDIT_SCORE = 550;

    /// @notice Maximum late penalty in basis points (20%).
    uint256 public constant MAX_LATE_PENALTY_BPS = 2000;

    /// @notice Maximum discount rate in basis points (50%).
    uint256 public constant MAX_DISCOUNT_BPS = 5000;

    /// @notice Maximum grace period (90 days).
    uint256 public constant MAX_GRACE_PERIOD = 90 days;

    /// @notice Maximum batch size for bulk invoice upload.
    uint256 public constant MAX_BATCH_SIZE = 50;

    // ──────────────────────────────────────────────────────────────
    // State
    // ──────────────────────────────────────────────────────────────

    /// @notice Invoice records keyed by invoice ID.
    mapping(bytes32 => Invoice) public invoices;

    /// @notice Factoring positions keyed by position ID.
    mapping(bytes32 => FactoringPosition) public factoringPositions;

    /// @notice All factoring position IDs for a given invoice.
    mapping(bytes32 => bytes32[]) public invoicePositions;

    /// @notice Credit profiles keyed by business address.
    mapping(address => CreditProfile) public creditProfiles;

    /// @notice Dispute records keyed by dispute ID.
    mapping(bytes32 => Dispute) public disputes;

    /// @notice Invoice ID to active dispute ID mapping.
    mapping(bytes32 => bytes32) public activeDisputes;

    /// @notice Collateral records keyed by a hash of (invoiceId, depositor).
    mapping(bytes32 => Collateral) public collaterals;

    /// @notice Invoices issued by a creditor.
    mapping(address => bytes32[]) public creditorInvoices;

    /// @notice Invoices owed by a debtor.
    mapping(address => bytes32[]) public debtorInvoices;

    /// @notice Supported settlement tokens.
    mapping(address => bool) public supportedTokens;

    /// @notice Reference to the BusinessRegistry for KYC validation.
    address public businessRegistry;

    /// @notice Monotonically increasing nonce for unique ID generation.
    uint256 public invoiceNonce;

    /// @notice Monotonically increasing nonce for positions.
    uint256 public positionNonce;

    /// @notice Monotonically increasing nonce for disputes.
    uint256 public disputeNonce;

    /// @notice Protocol fee on factoring transactions in basis points.
    uint256 public protocolFeeBps;

    /// @notice Address that receives protocol fees.
    address public protocolTreasury;

    // ──────────────────────────────────────────────────────────────
    // Events
    // ──────────────────────────────────────────────────────────────

    event InvoiceCreated(
        bytes32 indexed invoiceId,
        address indexed creditor,
        address indexed debtor,
        uint256 faceValue,
        uint256 maturityDate,
        address settlementToken
    );

    event InvoiceBatchCreated(
        address indexed creditor,
        uint256 count,
        uint256 totalFaceValue
    );

    event InvoiceChainLinked(
        bytes32 indexed childInvoiceId,
        bytes32 indexed parentInvoiceId,
        address indexed creditor
    );

    event InvoiceFinanced(
        bytes32 indexed invoiceId,
        bytes32 indexed positionId,
        address indexed factor,
        uint256 advanceAmount,
        uint256 discountBps
    );

    event InvoiceSettled(
        bytes32 indexed invoiceId,
        uint256 totalRepaid,
        uint256 settledAt
    );

    event InvoiceMarkedOverdue(
        bytes32 indexed invoiceId,
        uint256 daysOverdue,
        uint256 penaltyAmount
    );

    event FactoringPositionSettled(
        bytes32 indexed positionId,
        bytes32 indexed invoiceId,
        uint256 settledAmount
    );

    event CreditScoreUpdated(
        address indexed business,
        uint16 oldScore,
        uint16 newScore
    );

    event DisputeInitiated(
        bytes32 indexed disputeId,
        bytes32 indexed invoiceId,
        address indexed initiator,
        uint256 escrowAmount
    );

    event DisputeResolved(
        bytes32 indexed disputeId,
        bytes32 indexed invoiceId,
        DisputeOutcome outcome,
        uint256 creditorAward,
        uint256 debtorRefund
    );

    event CollateralDeposited(
        bytes32 indexed invoiceId,
        address indexed depositor,
        address token,
        uint256 amount
    );

    event CollateralReleased(
        bytes32 indexed invoiceId,
        address indexed depositor,
        uint256 amount
    );

    event InvoiceCancelled(bytes32 indexed invoiceId);
    event TokenSupported(address indexed token, bool supported);
    event ProtocolFeeUpdated(uint256 oldFee, uint256 newFee);
    event BusinessRegistryUpdated(address indexed oldRegistry, address indexed newRegistry);

    // ──────────────────────────────────────────────────────────────
    // Errors
    // ──────────────────────────────────────────────────────────────

    error ZeroAddress();
    error ZeroAmount();
    error UnsupportedToken();
    error InvoiceNotFound();
    error InvalidInvoiceStatus(InvoiceStatus current, InvoiceStatus expected);
    error MaturityInPast();
    error MaturityTooFar();
    error ExceedsFaceValue(uint256 requested, uint256 remaining);
    error InvalidDiscountRate();
    error InvalidPenaltyRate();
    error InvalidGracePeriod();
    error NotInvoiceParty();
    error InvoiceNotOverdue();
    error DisputeAlreadyActive();
    error DisputeNotFound();
    error DisputeNotPending();
    error BatchTooLarge(uint256 size, uint256 maxSize);
    error InsufficientCollateral();
    error CollateralAlreadyReleased();
    error InvalidCreditScore();
    error NotDebtor();
    error NotCreditor();
    error AlreadySettled();
    error InvalidFee();
    error ArrayLengthMismatch();

    // ──────────────────────────────────────────────────────────────
    // Constructor
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Deploys InvoiceFinancing with protocol fee configuration.
     * @param _admin           Admin address with full control.
     * @param _protocolTreasury Address that collects protocol fees.
     * @param _protocolFeeBps  Protocol fee in basis points.
     */
    constructor(
        address _admin,
        address _protocolTreasury,
        uint256 _protocolFeeBps
    ) {
        if (_admin == address(0)) revert ZeroAddress();
        if (_protocolTreasury == address(0)) revert ZeroAddress();
        if (_protocolFeeBps > 1000) revert InvalidFee(); // Max 10%

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);

        protocolTreasury = _protocolTreasury;
        protocolFeeBps = _protocolFeeBps;
    }

    // ──────────────────────────────────────────────────────────────
    // External — Invoice Creation
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Creates a new invoice representing a receivable.
     * @param _debtor          Address of the business that owes payment.
     * @param _faceValue       Invoice amount in settlement token units.
     * @param _settlementToken ERC20 token for settlement.
     * @param _maturityDate    Unix timestamp when payment is due.
     * @param _documentHash    Hash of the off-chain invoice document.
     * @param _gracePeriod     Grace period in seconds after maturity.
     * @param _latePenaltyBps  Late payment penalty in basis points.
     * @return invoiceId       Unique identifier for the invoice.
     */
    function createInvoice(
        address _debtor,
        uint256 _faceValue,
        address _settlementToken,
        uint256 _maturityDate,
        bytes32 _documentHash,
        uint256 _gracePeriod,
        uint256 _latePenaltyBps
    ) external whenNotPaused returns (bytes32 invoiceId) {
        if (_debtor == address(0)) revert ZeroAddress();
        if (_debtor == msg.sender) revert NotInvoiceParty();
        if (_faceValue == 0) revert ZeroAmount();
        if (!supportedTokens[_settlementToken]) revert UnsupportedToken();
        if (_maturityDate <= block.timestamp) revert MaturityInPast();
        if (_maturityDate > block.timestamp + 365 days) revert MaturityTooFar();
        if (_gracePeriod > MAX_GRACE_PERIOD) revert InvalidGracePeriod();
        if (_latePenaltyBps > MAX_LATE_PENALTY_BPS) revert InvalidPenaltyRate();

        invoiceId = keccak256(
            abi.encodePacked(msg.sender, _debtor, _faceValue, block.timestamp, invoiceNonce++)
        );

        invoices[invoiceId] = Invoice({
            invoiceId: invoiceId,
            creditor: msg.sender,
            debtor: _debtor,
            faceValue: _faceValue,
            amountFinanced: 0,
            amountRepaid: 0,
            settlementToken: _settlementToken,
            issuedAt: block.timestamp,
            maturityDate: _maturityDate,
            settledAt: 0,
            status: InvoiceStatus.CREATED,
            documentHash: _documentHash,
            parentInvoiceId: bytes32(0),
            gracePeriod: _gracePeriod,
            latePenaltyBps: _latePenaltyBps
        });

        creditorInvoices[msg.sender].push(invoiceId);
        debtorInvoices[_debtor].push(invoiceId);

        // Initialize credit profile if first interaction
        _initCreditProfileIfNeeded(msg.sender);
        _initCreditProfileIfNeeded(_debtor);
        creditProfiles[msg.sender].totalInvoicesIssued++;

        emit InvoiceCreated(invoiceId, msg.sender, _debtor, _faceValue, _maturityDate, _settlementToken);
    }

    /**
     * @notice Creates a child invoice linked to a parent, forming a supply chain.
     * @dev Used for multi-party invoice chains (supplier -> manufacturer -> distributor).
     * @param _parentInvoiceId Parent invoice to link to.
     * @param _debtor          Debtor for the child invoice.
     * @param _faceValue       Face value of the child invoice.
     * @param _maturityDate    Maturity date for the child invoice.
     * @param _documentHash    Hash of the child invoice document.
     * @param _gracePeriod     Grace period after maturity.
     * @param _latePenaltyBps  Late penalty in basis points.
     * @return invoiceId       Unique identifier for the child invoice.
     */
    function createChainedInvoice(
        bytes32 _parentInvoiceId,
        address _debtor,
        uint256 _faceValue,
        uint256 _maturityDate,
        bytes32 _documentHash,
        uint256 _gracePeriod,
        uint256 _latePenaltyBps
    ) external whenNotPaused returns (bytes32 invoiceId) {
        Invoice storage parent = invoices[_parentInvoiceId];
        if (parent.issuedAt == 0) revert InvoiceNotFound();

        // Only the debtor of the parent can create a child (they are now the creditor)
        if (msg.sender != parent.debtor) revert NotDebtor();
        if (_debtor == address(0) || _debtor == msg.sender) revert NotInvoiceParty();
        if (_faceValue == 0) revert ZeroAmount();
        if (!supportedTokens[parent.settlementToken]) revert UnsupportedToken();
        if (_maturityDate <= block.timestamp) revert MaturityInPast();
        if (_gracePeriod > MAX_GRACE_PERIOD) revert InvalidGracePeriod();
        if (_latePenaltyBps > MAX_LATE_PENALTY_BPS) revert InvalidPenaltyRate();

        invoiceId = keccak256(
            abi.encodePacked(msg.sender, _debtor, _faceValue, block.timestamp, invoiceNonce++)
        );

        invoices[invoiceId] = Invoice({
            invoiceId: invoiceId,
            creditor: msg.sender,
            debtor: _debtor,
            faceValue: _faceValue,
            amountFinanced: 0,
            amountRepaid: 0,
            settlementToken: parent.settlementToken,
            issuedAt: block.timestamp,
            maturityDate: _maturityDate,
            settledAt: 0,
            status: InvoiceStatus.CREATED,
            documentHash: _documentHash,
            parentInvoiceId: _parentInvoiceId,
            gracePeriod: _gracePeriod,
            latePenaltyBps: _latePenaltyBps
        });

        creditorInvoices[msg.sender].push(invoiceId);
        debtorInvoices[_debtor].push(invoiceId);

        _initCreditProfileIfNeeded(_debtor);
        creditProfiles[msg.sender].totalInvoicesIssued++;

        emit InvoiceCreated(invoiceId, msg.sender, _debtor, _faceValue, _maturityDate, parent.settlementToken);
        emit InvoiceChainLinked(invoiceId, _parentInvoiceId, msg.sender);
    }

    /**
     * @notice Batch upload invoices for supply chain financing.
     * @param _debtors         Array of debtor addresses.
     * @param _faceValues      Array of face values.
     * @param _settlementToken Shared settlement token for all invoices.
     * @param _maturityDates   Array of maturity dates.
     * @param _documentHashes  Array of document hashes.
     * @param _gracePeriod     Shared grace period for all invoices.
     * @param _latePenaltyBps  Shared late penalty for all invoices.
     * @return invoiceIds      Array of created invoice IDs.
     */
    function batchCreateInvoices(
        address[] calldata _debtors,
        uint256[] calldata _faceValues,
        address _settlementToken,
        uint256[] calldata _maturityDates,
        bytes32[] calldata _documentHashes,
        uint256 _gracePeriod,
        uint256 _latePenaltyBps
    ) external whenNotPaused returns (bytes32[] memory invoiceIds) {
        uint256 count = _debtors.length;
        if (count == 0) revert ZeroAmount();
        if (count > MAX_BATCH_SIZE) revert BatchTooLarge(count, MAX_BATCH_SIZE);
        if (
            count != _faceValues.length ||
            count != _maturityDates.length ||
            count != _documentHashes.length
        ) revert ArrayLengthMismatch();
        if (!supportedTokens[_settlementToken]) revert UnsupportedToken();
        if (_gracePeriod > MAX_GRACE_PERIOD) revert InvalidGracePeriod();
        if (_latePenaltyBps > MAX_LATE_PENALTY_BPS) revert InvalidPenaltyRate();

        invoiceIds = new bytes32[](count);
        uint256 totalFaceValue;

        _initCreditProfileIfNeeded(msg.sender);

        for (uint256 i; i < count;) {
            if (_debtors[i] == address(0) || _debtors[i] == msg.sender) revert NotInvoiceParty();
            if (_faceValues[i] == 0) revert ZeroAmount();
            if (_maturityDates[i] <= block.timestamp) revert MaturityInPast();

            bytes32 id = keccak256(
                abi.encodePacked(msg.sender, _debtors[i], _faceValues[i], block.timestamp, invoiceNonce++)
            );
            invoiceIds[i] = id;

            invoices[id] = Invoice({
                invoiceId: id,
                creditor: msg.sender,
                debtor: _debtors[i],
                faceValue: _faceValues[i],
                amountFinanced: 0,
                amountRepaid: 0,
                settlementToken: _settlementToken,
                issuedAt: block.timestamp,
                maturityDate: _maturityDates[i],
                settledAt: 0,
                status: InvoiceStatus.CREATED,
                documentHash: _documentHashes[i],
                parentInvoiceId: bytes32(0),
                gracePeriod: _gracePeriod,
                latePenaltyBps: _latePenaltyBps
            });

            creditorInvoices[msg.sender].push(id);
            debtorInvoices[_debtors[i]].push(id);

            _initCreditProfileIfNeeded(_debtors[i]);
            creditProfiles[msg.sender].totalInvoicesIssued++;
            totalFaceValue += _faceValues[i];

            emit InvoiceCreated(id, msg.sender, _debtors[i], _faceValues[i], _maturityDates[i], _settlementToken);

            unchecked { ++i; }
        }

        emit InvoiceBatchCreated(msg.sender, count, totalFaceValue);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Factoring (Financing)
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Finances an invoice (full or partial) by advancing funds to the creditor.
     * @dev The factor transfers the advance amount to the creditor and receives
     *      the right to collect the face value (or portion) at maturity.
     *      Discount rate is dynamically influenced by debtor credit score.
     * @param _invoiceId     Invoice to finance.
     * @param _advanceAmount Amount to advance to the creditor.
     * @param _discountBps   Discount rate in basis points.
     * @return positionId    Unique identifier for the factoring position.
     */
    function financeInvoice(
        bytes32 _invoiceId,
        uint256 _advanceAmount,
        uint256 _discountBps
    ) external whenNotPaused nonReentrant onlyRole(FACTOR_ROLE) returns (bytes32 positionId) {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        if (
            inv.status != InvoiceStatus.CREATED &&
            inv.status != InvoiceStatus.PARTIALLY_FINANCED
        ) {
            revert InvalidInvoiceStatus(inv.status, InvoiceStatus.CREATED);
        }
        if (_advanceAmount == 0) revert ZeroAmount();
        if (_discountBps > MAX_DISCOUNT_BPS) revert InvalidDiscountRate();

        uint256 remainingFinanceable = inv.faceValue - inv.amountFinanced;
        if (_advanceAmount > remainingFinanceable) {
            revert ExceedsFaceValue(_advanceAmount, remainingFinanceable);
        }

        // Calculate expected return: advance + discount
        uint256 expectedReturn = _advanceAmount + (_advanceAmount * _discountBps / 10_000);
        // Cap expected return at the proportional face value
        uint256 proportionalFaceValue = (inv.faceValue * _advanceAmount) / (inv.faceValue - inv.amountFinanced);
        if (expectedReturn > proportionalFaceValue) {
            expectedReturn = proportionalFaceValue;
        }

        positionId = keccak256(
            abi.encodePacked(msg.sender, _invoiceId, _advanceAmount, block.timestamp, positionNonce++)
        );

        factoringPositions[positionId] = FactoringPosition({
            positionId: positionId,
            invoiceId: _invoiceId,
            factor: msg.sender,
            advanceAmount: _advanceAmount,
            discountBps: _discountBps,
            expectedReturn: expectedReturn,
            financedAt: block.timestamp,
            settled: false,
            settledAmount: 0
        });

        invoicePositions[_invoiceId].push(positionId);
        inv.amountFinanced += _advanceAmount;

        // Update invoice status
        if (inv.amountFinanced >= inv.faceValue) {
            inv.status = InvoiceStatus.FULLY_FINANCED;
        } else {
            inv.status = InvoiceStatus.PARTIALLY_FINANCED;
        }

        // Calculate protocol fee
        uint256 protocolFee = (_advanceAmount * protocolFeeBps) / 10_000;
        uint256 netAdvance = _advanceAmount - protocolFee;

        // Transfer advance from factor to creditor
        IERC20(inv.settlementToken).safeTransferFrom(msg.sender, inv.creditor, netAdvance);
        if (protocolFee > 0) {
            IERC20(inv.settlementToken).safeTransferFrom(msg.sender, protocolTreasury, protocolFee);
        }

        // Update credit profile
        creditProfiles[inv.creditor].totalValueFinanced += _advanceAmount;

        emit InvoiceFinanced(_invoiceId, positionId, msg.sender, _advanceAmount, _discountBps);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Settlement
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Debtor repays an invoice (full or partial payment).
     * @dev Payments are distributed pro-rata to factoring positions. If no
     *      positions exist, payment goes directly to the creditor.
     * @param _invoiceId Invoice to repay.
     * @param _amount    Amount to repay in settlement token units.
     */
    function repayInvoice(
        bytes32 _invoiceId,
        uint256 _amount
    ) external whenNotPaused nonReentrant {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        if (msg.sender != inv.debtor) revert NotDebtor();
        if (_amount == 0) revert ZeroAmount();
        if (inv.status == InvoiceStatus.SETTLED || inv.status == InvoiceStatus.CANCELLED) {
            revert InvalidInvoiceStatus(inv.status, InvoiceStatus.CREATED);
        }

        uint256 totalOwed = _calculateTotalOwed(inv);
        uint256 remaining = totalOwed - inv.amountRepaid;
        uint256 payAmount = _amount > remaining ? remaining : _amount;

        // Transfer payment from debtor
        IERC20(inv.settlementToken).safeTransferFrom(msg.sender, address(this), payAmount);
        inv.amountRepaid += payAmount;

        // Distribute to factoring positions pro-rata
        _distributePayment(_invoiceId, payAmount, inv);

        // Check if fully settled
        if (inv.amountRepaid >= totalOwed) {
            inv.status = InvoiceStatus.SETTLED;
            inv.settledAt = block.timestamp;

            // Update credit profile
            CreditProfile storage cp = creditProfiles[inv.debtor];
            cp.totalInvoicesPaid++;
            cp.totalValueRepaid += inv.amountRepaid;

            // Update days late for credit scoring
            if (block.timestamp > inv.maturityDate) {
                uint256 daysLate = (block.timestamp - inv.maturityDate) / 1 days;
                uint256 totalPayments = cp.totalInvoicesPaid;
                cp.averageDaysLate = ((cp.averageDaysLate * (totalPayments - 1)) + daysLate) / totalPayments;
            }

            _updateCreditScore(inv.debtor);

            emit InvoiceSettled(_invoiceId, inv.amountRepaid, block.timestamp);
        }
    }

    /**
     * @notice Marks an invoice as overdue and applies late penalties.
     * @dev Can be called by anyone after the maturity date + grace period.
     * @param _invoiceId Invoice to mark as overdue.
     */
    function markOverdue(bytes32 _invoiceId) external whenNotPaused {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        if (inv.status == InvoiceStatus.SETTLED || inv.status == InvoiceStatus.CANCELLED) {
            revert InvalidInvoiceStatus(inv.status, InvoiceStatus.CREATED);
        }
        if (block.timestamp <= inv.maturityDate + inv.gracePeriod) revert InvoiceNotOverdue();

        inv.status = InvoiceStatus.OVERDUE;

        uint256 daysOverdue = (block.timestamp - inv.maturityDate) / 1 days;
        uint256 penaltyAmount = (inv.faceValue * inv.latePenaltyBps * daysOverdue) / (10_000 * 365);

        // Update debtor credit profile
        CreditProfile storage cp = creditProfiles[inv.debtor];
        cp.totalInvoicesDefaulted++;
        _updateCreditScore(inv.debtor);

        emit InvoiceMarkedOverdue(_invoiceId, daysOverdue, penaltyAmount);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Dispute Resolution
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Initiates a dispute on an invoice with escrow.
     * @dev Either the creditor or debtor can initiate. Disputed funds are
     *      held in escrow until an arbiter resolves the dispute.
     * @param _invoiceId Invoice to dispute.
     * @param _reason    Human-readable reason for the dispute.
     * @return disputeId Unique identifier for the dispute.
     */
    function initiateDispute(
        bytes32 _invoiceId,
        string calldata _reason
    ) external whenNotPaused nonReentrant returns (bytes32 disputeId) {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        if (msg.sender != inv.creditor && msg.sender != inv.debtor) revert NotInvoiceParty();
        if (activeDisputes[_invoiceId] != bytes32(0)) revert DisputeAlreadyActive();
        if (inv.status == InvoiceStatus.SETTLED || inv.status == InvoiceStatus.CANCELLED) {
            revert InvalidInvoiceStatus(inv.status, InvoiceStatus.CREATED);
        }

        disputeId = keccak256(
            abi.encodePacked(_invoiceId, msg.sender, block.timestamp, disputeNonce++)
        );

        address respondent = msg.sender == inv.creditor ? inv.debtor : inv.creditor;

        // Escrow the remaining owed amount
        uint256 escrowAmount = inv.faceValue - inv.amountRepaid;

        disputes[disputeId] = Dispute({
            disputeId: disputeId,
            invoiceId: _invoiceId,
            initiator: msg.sender,
            respondent: respondent,
            reason: _reason,
            escrowAmount: escrowAmount,
            outcome: DisputeOutcome.PENDING,
            initiatedAt: block.timestamp,
            resolvedAt: 0,
            arbiter: address(0),
            creditorAward: 0,
            debtorRefund: 0
        });

        activeDisputes[_invoiceId] = disputeId;
        inv.status = InvoiceStatus.DISPUTED;

        emit DisputeInitiated(disputeId, _invoiceId, msg.sender, escrowAmount);
    }

    /**
     * @notice Resolves a dispute with binding arbitration.
     * @dev Only callable by addresses with ARBITER_ROLE.
     * @param _disputeId     Dispute to resolve.
     * @param _outcome       Resolution outcome.
     * @param _creditorAward Amount awarded to the creditor.
     * @param _debtorRefund  Amount refunded to the debtor.
     */
    function resolveDispute(
        bytes32 _disputeId,
        DisputeOutcome _outcome,
        uint256 _creditorAward,
        uint256 _debtorRefund
    ) external whenNotPaused nonReentrant onlyRole(ARBITER_ROLE) {
        Dispute storage d = disputes[_disputeId];
        if (d.initiatedAt == 0) revert DisputeNotFound();
        if (d.outcome != DisputeOutcome.PENDING) revert DisputeNotPending();
        require(
            _outcome != DisputeOutcome.PENDING,
            "InvoiceFinancing: invalid outcome"
        );

        Invoice storage inv = invoices[d.invoiceId];

        d.outcome = _outcome;
        d.resolvedAt = block.timestamp;
        d.arbiter = msg.sender;
        d.creditorAward = _creditorAward;
        d.debtorRefund = _debtorRefund;

        inv.status = InvoiceStatus.RESOLVED;
        delete activeDisputes[d.invoiceId];

        // Distribute escrowed funds according to arbitration
        if (_creditorAward > 0) {
            IERC20(inv.settlementToken).safeTransfer(inv.creditor, _creditorAward);
        }
        if (_debtorRefund > 0) {
            IERC20(inv.settlementToken).safeTransfer(inv.debtor, _debtorRefund);
        }

        emit DisputeResolved(_disputeId, d.invoiceId, _outcome, _creditorAward, _debtorRefund);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Collateral Management
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Deposits collateral against an invoice for under-collateralized financing.
     * @param _invoiceId Invoice to collateralize.
     * @param _token     Collateral token address.
     * @param _amount    Collateral amount.
     */
    function depositCollateral(
        bytes32 _invoiceId,
        address _token,
        uint256 _amount
    ) external whenNotPaused nonReentrant {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        if (_amount == 0) revert ZeroAmount();
        if (!supportedTokens[_token]) revert UnsupportedToken();

        bytes32 collateralKey = keccak256(abi.encodePacked(_invoiceId, msg.sender));

        Collateral storage col = collaterals[collateralKey];
        col.depositor = msg.sender;
        col.token = _token;
        col.amount += _amount;
        col.invoiceId = _invoiceId;

        IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);

        emit CollateralDeposited(_invoiceId, msg.sender, _token, _amount);
    }

    /**
     * @notice Releases collateral after invoice settlement.
     * @param _invoiceId Invoice whose collateral to release.
     * @param _depositor Address of the collateral depositor.
     */
    function releaseCollateral(
        bytes32 _invoiceId,
        address _depositor
    ) external whenNotPaused nonReentrant {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        require(
            inv.status == InvoiceStatus.SETTLED || inv.status == InvoiceStatus.RESOLVED ||
            inv.status == InvoiceStatus.CANCELLED,
            "InvoiceFinancing: invoice not finalized"
        );

        bytes32 collateralKey = keccak256(abi.encodePacked(_invoiceId, _depositor));
        Collateral storage col = collaterals[collateralKey];
        if (col.released) revert CollateralAlreadyReleased();
        if (col.amount == 0) revert InsufficientCollateral();

        col.released = true;
        uint256 amount = col.amount;

        IERC20(col.token).safeTransfer(_depositor, amount);

        emit CollateralReleased(_invoiceId, _depositor, amount);
    }

    // ──────────────────────────────────────────────────────────────
    // External — Credit Scoring
    // ──────────────────────────────────────────────────────────────

    /**
     * @notice Manually adjusts a business credit score (analyst override).
     * @dev Only callable by addresses with CREDIT_ANALYST_ROLE.
     * @param _business Business address.
     * @param _newScore New credit score (300-850).
     */
    function adjustCreditScore(
        address _business,
        uint16 _newScore
    ) external onlyRole(CREDIT_ANALYST_ROLE) {
        if (_newScore < MIN_CREDIT_SCORE || _newScore > MAX_CREDIT_SCORE) {
            revert InvalidCreditScore();
        }

        _initCreditProfileIfNeeded(_business);

        uint16 oldScore = creditProfiles[_business].creditScore;
        creditProfiles[_business].creditScore = _newScore;
        creditProfiles[_business].lastUpdated = block.timestamp;

        emit CreditScoreUpdated(_business, oldScore, _newScore);
    }

    /**
     * @notice Cancels an unfunded invoice. Only the creditor can cancel.
     * @param _invoiceId Invoice to cancel.
     */
    function cancelInvoice(bytes32 _invoiceId) external whenNotPaused {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        if (msg.sender != inv.creditor) revert NotCreditor();
        if (inv.status != InvoiceStatus.CREATED) {
            revert InvalidInvoiceStatus(inv.status, InvoiceStatus.CREATED);
        }

        inv.status = InvoiceStatus.CANCELLED;
        emit InvoiceCancelled(_invoiceId);
    }

    // ──────────────────────────────────────────────────────────────
    // View Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Returns the full invoice record.
    function getInvoice(bytes32 _invoiceId) external view returns (Invoice memory) {
        return invoices[_invoiceId];
    }

    /// @notice Returns the credit profile for a business.
    function getCreditProfile(address _business) external view returns (CreditProfile memory) {
        return creditProfiles[_business];
    }

    /// @notice Returns the suggested discount rate based on debtor credit score.
    function getSuggestedDiscountRate(address _debtor) external view returns (uint256) {
        CreditProfile storage cp = creditProfiles[_debtor];
        if (cp.lastUpdated == 0) return 1500; // 15% for unknown entities

        // Higher credit score = lower discount (better rates)
        if (cp.creditScore >= 750) return 200;   // 2%
        if (cp.creditScore >= 650) return 500;   // 5%
        if (cp.creditScore >= 550) return 1000;  // 10%
        if (cp.creditScore >= 450) return 1500;  // 15%
        return 2500;                              // 25%
    }

    /// @notice Returns the total amount owed on an invoice including penalties.
    function getTotalOwed(bytes32 _invoiceId) external view returns (uint256) {
        Invoice storage inv = invoices[_invoiceId];
        if (inv.issuedAt == 0) revert InvoiceNotFound();
        return _calculateTotalOwed(inv);
    }

    /// @notice Returns all factoring position IDs for an invoice.
    function getInvoicePositions(bytes32 _invoiceId) external view returns (bytes32[] memory) {
        return invoicePositions[_invoiceId];
    }

    /// @notice Returns a factoring position record.
    function getFactoringPosition(bytes32 _positionId) external view returns (FactoringPosition memory) {
        return factoringPositions[_positionId];
    }

    /// @notice Returns the dispute record for a given dispute ID.
    function getDispute(bytes32 _disputeId) external view returns (Dispute memory) {
        return disputes[_disputeId];
    }

    /// @notice Returns invoices created by a creditor.
    function getCreditorInvoices(address _creditor) external view returns (bytes32[] memory) {
        return creditorInvoices[_creditor];
    }

    /// @notice Returns invoices owed by a debtor.
    function getDebtorInvoices(address _debtor) external view returns (bytes32[] memory) {
        return debtorInvoices[_debtor];
    }

    // ──────────────────────────────────────────────────────────────
    // Admin Functions
    // ──────────────────────────────────────────────────────────────

    /// @notice Adds or removes a supported settlement token.
    function setSupportedToken(address _token, bool _supported) external onlyRole(ADMIN_ROLE) {
        if (_token == address(0)) revert ZeroAddress();
        supportedTokens[_token] = _supported;
        emit TokenSupported(_token, _supported);
    }

    /// @notice Updates the protocol fee.
    function setProtocolFee(uint256 _newFeeBps) external onlyRole(ADMIN_ROLE) {
        if (_newFeeBps > 1000) revert InvalidFee();
        uint256 oldFee = protocolFeeBps;
        protocolFeeBps = _newFeeBps;
        emit ProtocolFeeUpdated(oldFee, _newFeeBps);
    }

    /// @notice Updates the business registry address.
    function setBusinessRegistry(address _registry) external onlyRole(ADMIN_ROLE) {
        if (_registry == address(0)) revert ZeroAddress();
        address old = businessRegistry;
        businessRegistry = _registry;
        emit BusinessRegistryUpdated(old, _registry);
    }

    /// @notice Emergency pause.
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    /// @notice Resume operations.
    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    // ──────────────────────────────────────────────────────────────
    // Internal Helpers
    // ──────────────────────────────────────────────────────────────

    /**
     * @dev Initializes a credit profile if the business has not interacted before.
     * @param _business Business address.
     */
    function _initCreditProfileIfNeeded(address _business) internal {
        if (creditProfiles[_business].lastUpdated == 0) {
            creditProfiles[_business] = CreditProfile({
                creditScore: DEFAULT_CREDIT_SCORE,
                totalInvoicesIssued: 0,
                totalInvoicesPaid: 0,
                totalInvoicesDefaulted: 0,
                totalValueFinanced: 0,
                totalValueRepaid: 0,
                averageDaysLate: 0,
                lastUpdated: block.timestamp
            });
        }
    }

    /**
     * @dev Updates credit score based on payment history.
     * @param _business Business address to update.
     */
    function _updateCreditScore(address _business) internal {
        CreditProfile storage cp = creditProfiles[_business];
        uint16 oldScore = cp.creditScore;

        uint256 totalInvoices = cp.totalInvoicesPaid + cp.totalInvoicesDefaulted;
        if (totalInvoices == 0) return;

        // Payment ratio: percentage of invoices paid on time (0-100)
        uint256 paymentRatio = (cp.totalInvoicesPaid * 100) / totalInvoices;

        // Base score from payment ratio (300-700 range)
        uint256 baseScore = 300 + (paymentRatio * 4);

        // Bonus for low average days late (up to +100)
        uint256 lateBonus;
        if (cp.averageDaysLate == 0) {
            lateBonus = 100;
        } else if (cp.averageDaysLate <= 7) {
            lateBonus = 50;
        } else if (cp.averageDaysLate <= 30) {
            lateBonus = 20;
        }

        // Volume bonus (up to +50 for large repayment history)
        uint256 volumeBonus;
        if (cp.totalValueRepaid > 10_000_000 * 1e6) {
            volumeBonus = 50;
        } else if (cp.totalValueRepaid > 1_000_000 * 1e6) {
            volumeBonus = 30;
        } else if (cp.totalValueRepaid > 100_000 * 1e6) {
            volumeBonus = 10;
        }

        uint256 newScore = baseScore + lateBonus + volumeBonus;
        if (newScore > MAX_CREDIT_SCORE) newScore = MAX_CREDIT_SCORE;
        if (newScore < MIN_CREDIT_SCORE) newScore = MIN_CREDIT_SCORE;

        cp.creditScore = uint16(newScore);
        cp.lastUpdated = block.timestamp;

        if (oldScore != uint16(newScore)) {
            emit CreditScoreUpdated(_business, oldScore, uint16(newScore));
        }
    }

    /**
     * @dev Calculates total amount owed on an invoice including late penalties.
     * @param inv Invoice storage reference.
     * @return Total amount owed.
     */
    function _calculateTotalOwed(Invoice storage inv) internal view returns (uint256) {
        uint256 totalOwed = inv.faceValue;

        // Add late penalty if overdue
        if (block.timestamp > inv.maturityDate + inv.gracePeriod) {
            uint256 daysOverdue = (block.timestamp - inv.maturityDate) / 1 days;
            uint256 penalty = (inv.faceValue * inv.latePenaltyBps * daysOverdue) / (10_000 * 365);
            totalOwed += penalty;
        }

        return totalOwed;
    }

    /**
     * @dev Distributes a payment pro-rata to factoring positions.
     * @param _invoiceId Invoice being repaid.
     * @param _amount    Payment amount to distribute.
     * @param inv        Invoice storage reference.
     */
    function _distributePayment(
        bytes32 _invoiceId,
        uint256 _amount,
        Invoice storage inv
    ) internal {
        bytes32[] storage positions = invoicePositions[_invoiceId];
        uint256 positionCount = positions.length;

        if (positionCount == 0) {
            // No factoring positions — pay creditor directly
            IERC20(inv.settlementToken).safeTransfer(inv.creditor, _amount);
            return;
        }

        uint256 distributed;

        for (uint256 i; i < positionCount;) {
            FactoringPosition storage pos = factoringPositions[positions[i]];
            if (!pos.settled) {
                uint256 remaining = pos.expectedReturn - pos.settledAmount;
                // Pro-rata share based on advance amount relative to total financed
                uint256 share = (_amount * pos.advanceAmount) / inv.amountFinanced;
                if (share > remaining) share = remaining;

                pos.settledAmount += share;
                distributed += share;

                IERC20(inv.settlementToken).safeTransfer(pos.factor, share);

                if (pos.settledAmount >= pos.expectedReturn) {
                    pos.settled = true;
                    emit FactoringPositionSettled(pos.positionId, _invoiceId, pos.settledAmount);
                }
            }

            unchecked { ++i; }
        }

        // Any remainder goes to the creditor
        uint256 creditorShare = _amount - distributed;
        if (creditorShare > 0) {
            IERC20(inv.settlementToken).safeTransfer(inv.creditor, creditorShare);
        }
    }
}

